using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageGeneratedCodeTests
{
    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            public enum Color { Red, Green }

            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)] public int A { get; set; }
                [Key(1)] public Color C { get; set; }
            }

            [MessagePackObject(true)]
            public class StringKeyed
            {
                public int B { get; set; }
            }

            [Union(0, typeof(UnionCase))]
            public interface IUnionBase { }

            [MessagePackObject]
            public class UnionCase : IUnionBase
            {
                [Key(0)] public int X { get; set; }
            }

            [GeneratedMessagePackResolver]
            partial class MyResolver { }
        }
        """;

    [Fact]
    public async Task GeneratedFormattersAndResolverAreExcludedFromCodeCoverage()
    {
        (HashSet<string> checkedTypes, HashSet<string> missing) = await AnalyzeAsync(new CSharpParseOptions(LanguageVersion.Latest));
        Assert.Contains("TestNs.MyResolver", checkedTypes);
        Assert.True(checkedTypes.Count >= 3, "Expected the generator to emit a resolver and formatters. Found: " + string.Join(", ", checkedTypes));
        Assert.True(missing.Count == 0, "Generated types without ExcludeFromCodeCoverage: " + string.Join(", ", missing));
    }

    private static async Task<(HashSet<string> Checked, HashSet<string> Missing)> AnalyzeAsync(CSharpParseOptions parseOptions)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = Enumerable.Concat<MetadataReference>(framework, ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        SyntaxTree inputTree = CSharpSyntaxTree.ParseText(Source, parseOptions);
        CSharpCompilation compilation = CSharpCompilation.Create("ReceiptsCoverageAssembly", new[] { inputTree }, references, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> _);
        GeneratorDriverRunResult run = driver.GetRunResult();
        foreach (GeneratorRunResult result in run.Results)
        {
            Assert.Null(result.Exception);
        }

        HashSet<string> checkedTypes = new();
        HashSet<string> missing = new();
        foreach (SyntaxTree tree in output.SyntaxTrees)
        {
            if (ReferenceEquals(tree, inputTree))
            {
                continue;
            }

            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax cls in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                INamedTypeSymbol? symbol = model.GetDeclaredSymbol(cls);
                if (symbol is null)
                {
                    continue;
                }

                bool isGeneratedPlumbing = symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" || i.Name == "IFormatterResolver");
                if (!isGeneratedPlumbing)
                {
                    continue;
                }

                string name = symbol.ToDisplayString();
                checkedTypes.Add(name);
                bool hasAttribute = symbol.GetAttributes().Any(a => a.AttributeClass?.Name == "ExcludeFromCodeCoverageAttribute");
                if (!hasAttribute)
                {
                    missing.Add(name);
                }
            }
        }

        return (checkedTypes, missing);
    }
}

